package com.vandorlabs.neoforge.reservoir.client;
import com.vandorlabs.neoforge.ModernFinishCatalog;import com.vandorlabs.neoforge.reservoir.*;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.client.renderer.texture.*;import net.minecraft.core.Direction;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;import net.neoforged.neoforge.client.extensions.common.IClientFluidTypeExtensions;
/** Authored Source shell templates, with live charge and per-cell fluid levels. */
public final class NativeBufferRenderer<T extends NativeBufferEntity> implements BlockEntityRenderer<T> {
 static final BatteryGeometryCache BATTERY=new BatteryGeometryCache();static final HexTankGeometryCache TANK=new HexTankGeometryCache(NativeHexTankEntity.CAPACITY);
 private static final ResourceLocation ATLAS=TextureAtlas.LOCATION_BLOCKS;
 public NativeBufferRenderer(BlockEntityRendererProvider.Context context){}
 private static final java.util.Map<String,TextureAtlasSprite> SPRITES=new java.util.LinkedHashMap<>(32,.75F,true);
 private static TextureAtlasSprite sprite(String name){var found=SPRITES.get(name);if(found!=null)return found;found=Minecraft.getInstance().getTextureAtlas(ATLAS).apply(ResourceLocation.parse(name));if(SPRITES.size()>=256)SPRITES.remove(SPRITES.keySet().iterator().next());SPRITES.put(name,found);return found;}
 private static TextureAtlasSprite casing(NativeBufferEntity tile){return tile.casing()==-1?sprite("vandorlabs:blocks/matter/casing"):sprite(ModernFinishCatalog.option(tile.casing()).texture());}
 private static int axis(Direction facing){return facing.getAxis()==Direction.Axis.X?0:facing.getAxis()==Direction.Axis.Z?2:1;}
 private static final class Sink implements BatteryGeometryCache.Sink,HexTankGeometryCache.Sink {
  final PoseStack.Pose pose;VertexConsumer buffer;final TextureAtlasSprite[] textures;final int light,overlay;TextureAtlasSprite current;float nx,ny,nz,r=1,g=1,b=1;
  Sink(PoseStack.Pose pose,VertexConsumer buffer,TextureAtlasSprite[] textures,int light,int overlay){this.pose=pose;this.buffer=buffer;this.textures=textures;this.light=light;this.overlay=overlay;}
  public void beginQuad(int material,float nx,float ny,float nz){beginQuad(material,0xffffff,true,nx,ny,nz);}
  public void beginQuad(int material,int color,boolean diffuse,float nx,float ny,float nz){current=textures[material];this.nx=nx;this.ny=ny;this.nz=nz;float shade=diffuse?nx*nx*.6F+ny*ny*(ny>0?1:.5F)+nz*nz*.8F:1;r=(color>>16&255)/255F*shade;g=(color>>8&255)/255F*shade;b=(color&255)/255F*shade;}
  public void vertex(double x,double y,double z,double u,double v){buffer.addVertex(pose.pose(),(float)x,(float)y,(float)z).setColor(r,g,b,1).setUv(current.getU((float)u/16),current.getV((float)v/16)).setOverlay(overlay).setLight(light).setNormal(pose,nx,ny,nz);}
 }
 @Override public void render(T tile,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){if(tile instanceof NativeBatteryEntity battery)battery(battery,pose,buffers,light,overlay);else if(tile instanceof NativeHexTankEntity tank)tank(tank,pose,buffers,light,overlay);}
 private static void battery(NativeBatteryEntity tile,PoseStack pose,MultiBufferSource buffers,int light,int overlay){var casing=casing(tile);var textures=new TextureAtlasSprite[]{casing,tile.casing()==-1?sprite("vandorlabs:blocks/imported/power/battery_cell_bank"):casing,sprite("vandorlabs:blocks/matter/energy_in"),sprite("vandorlabs:blocks/matter/energy_out")};var buffer=buffers.getBuffer(RenderType.entityCutoutNoCull(ATLAS));BATTERY.mesh(tile.blockShape(),axis(tile.facing()),tile.facing().getAxisDirection()==Direction.AxisDirection.POSITIVE).emit(new Sink(pose.last(),buffer,textures,light,overlay));var white=sprite("vandorlabs:blocks/reservoir/white");double low=tile.blockShape()||tile.facing().getAxis()==Direction.Axis.Y?0:.5-Math.sqrt(3)/4;var indicator=new Sink(pose.last(),buffer,new TextureAtlasSprite[]{white},light,overlay);indicator(indicator,low,tile.amount()/(double)tile.capacity());indicator(indicator,1-low,tile.amount()/(double)tile.capacity());}
 private static void indicator(Sink sink,double y,double charge){double direction=y>.5?1:-1,surface=y+direction*.001,detail=surface+direction*.0005;rect(sink,.27,.73,.36,.64,surface,direction,0x18221f);for(int i=0;i<10;i++){double left=.29+i*.042,right=left+.033;rect(sink,left,right,.39,.61,detail,direction,0x233f2b);double fill=Math.max(0,Math.min(1,charge*10-i));if(fill>0)rect(sink,left,left+(right-left)*fill,.39,.61,detail+direction*.0003,direction,0x62ed82);}}
 private static void rect(Sink sink,double left,double right,double front,double back,double y,double normal,int color){sink.beginQuad(0,color,false,0,(float)normal,0);sink.vertex(left,y,front,0,0);sink.vertex(left,y,back,0,16);sink.vertex(right,y,back,16,16);sink.vertex(right,y,front,16,0);}
 private static void tank(NativeHexTankEntity tile,PoseStack pose,MultiBufferSource buffers,int light,int overlay){var part=NativeTankGroups.part(tile);if(part.x!=0||part.y!=0)return;pose.pushPose();try{switch(tile.facing().getAxis()){case X->pose.scale(1,part.size,part.size);case Y->pose.scale(part.size,1,part.size);case Z->pose.scale(part.size,part.size,1);}var textures=new TextureAtlasSprite[]{casing(tile),sprite("vandorlabs:blocks/matter/tank_empty"),sprite("vandorlabs:blocks/matter/port"),sprite("minecraft:block/glass")};var geometry=TANK.template(tile.blockShape(),axis(tile.facing()),tile.settings().layout==1,part.size);geometry.shell.emit(new Sink(pose.last(),buffers.getBuffer(RenderType.entityCutoutNoCull(ATLAS)),textures,light,overlay));var fluid=tile.visibleFluid();int total=fluid.getAmount();if(tile.getLevel()!=null){total=0;var root=tile.getBlockPos();var a=tile.facing().getAxis();for(int x=0;x<part.size;x++)for(int y=0;y<part.size;y++)if(tile.getLevel().getBlockEntity(root.relative(NativeTankGroups.right(a),x).relative(NativeTankGroups.up(a),y)) instanceof NativeHexTankEntity cell){var stored=cell.visibleFluid();total+=stored.getAmount();if(fluid.isEmpty()&&!stored.isEmpty())fluid=stored;}}int amount=total/(part.size*part.size);if(!fluid.isEmpty()&&amount>0){var extension=IClientFluidTypeExtensions.of(fluid.getFluid());var still=extension.getStillTexture(fluid);var water=Minecraft.getInstance().getTextureAtlas(ATLAS).apply(still==null?MissingTextureAtlasSprite.getLocation():still);int color=extension.getTintColor(fluid);var sink=new Sink(pose.last(),buffers.getBuffer(RenderType.entityTranslucent(ATLAS)),new TextureAtlasSprite[]{water},light,overlay);sink.beginQuad(0,color,false,0,1,0);var outline=tile.facing().getAxis()==Direction.Axis.Y?HexTankGeometryCache.fullOutline(tile.blockShape()):TANK.fluidOutline(tile.blockShape(),amount);double high=tile.facing().getAxis()==Direction.Axis.Y?.04+.92*Math.min(1,amount/(double)NativeHexTankEntity.CAPACITY):.96;for(int edge=0;edge<outline.size();edge++){int next=(edge+1)%outline.size();point(sink,outline.x(edge),high,outline.z(edge),tile.facing(),0,0);point(sink,outline.x(edge),.0405,outline.z(edge),tile.facing(),0,16);point(sink,outline.x(next),.0405,outline.z(next),tile.facing(),16,16);point(sink,outline.x(next),high,outline.z(next),tile.facing(),16,0);}cap(sink,outline,high,tile.facing());cap(sink,outline,.0405,tile.facing());}geometry.windows.emit(new Sink(pose.last(),buffers.getBuffer(RenderType.entityTranslucent(ATLAS)),textures,light,overlay));}finally{pose.popPose();}}
 private static void point(Sink sink,double x,double y,double z,Direction face,double u,double v){x=.5+(x-.5)*.895;z=.5+(z-.5)*.895;switch(face.getAxis()){case X->sink.vertex(y,z,x,u,v);case Y->sink.vertex(x,y,z,u,v);case Z->sink.vertex(x,z,y,u,v);}}
 private static void cap(Sink sink,HexTankGeometryCache.Outline outline,double y,Direction face){double cx=0,cz=0;for(int i=0;i<outline.size();i++){cx+=outline.x(i);cz+=outline.z(i);}cx/=outline.size();cz/=outline.size();for(int i=0;i<outline.size();i++){int n=(i+1)%outline.size();point(sink,cx,y,cz,face,cx*16,cz*16);point(sink,outline.x(i),y,outline.z(i),face,outline.x(i)*16,outline.z(i)*16);point(sink,outline.x(n),y,outline.z(n),face,outline.x(n)*16,outline.z(n)*16);point(sink,cx,y,cz,face,cx*16,cz*16);}}
 @Override public AABB getRenderBoundingBox(T tile){return new AABB(tile.getBlockPos()).inflate(3);}
 static void clear(){BATTERY.clear();TANK.clear();SPRITES.clear();}
}
